const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a rough bounding box for the Sierra Nevada mountains
  const sierraNevada = ee.Geometry.Polygon(
    [
      [-121.2, 36.0],
      [-117.8, 36.0],
      [-117.8, 41.0],
      [-121.2, 41.0],
      [-121.2, 36.0]
    ]
  );

  const dates = {
    'Jan 1': '2022-01-01',
    'Apr 1': '2022-04-01',
    'May 4': '2022-05-04'
  };

  const collection = ee.ImageCollection('MODIS/006/MOD10A1');
  const scale = 5000; // Use a reasonable scale to avoid memory issues and timeouts

  const results = {};

  for (const dateKey in dates) {
    const targetDate = dates[dateKey];
    const startDate = ee.Date(targetDate);
    const endDate = startDate.advance(1, 'day'); // Get a 1-day range

    let imgCol = collection.filterDate(startDate, endDate).filterBounds(sierraNevada);

    if (imgCol.size().getInfo() === 0) {
      console.log(`No images found for ${dateKey} (${targetDate}).`);
      console.log("C1");
      return;
    }

    // Get the first image for the day (MOD10A1 is daily)
    let image = imgCol.first();

    // Select the NDSI_Snow_Fraction band
    let snowFraction = image.select('NDSI_Snow_Fraction');

    // MODIS NDSI_Snow_Fraction values:
    // 0-10000: Snow fraction (scaled by 10000)
    // 250: No decision
    // 251: Ocean
    // 252: Lake
    // 253: Cloud
    // 254: Land
    // 255: No data
    // Mask out non-snow values (clouds, land, water, no data)
    let maskedSnowFraction = snowFraction.updateMask(
      snowFraction.gte(0).and(snowFraction.lte(10000))
    );

    // Calculate valid pixel count
    const pixelCount = maskedSnowFraction.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: sierraNevada,
      scale: scale,
      maxPixels: 1e9
    }).get('NDSI_Snow_Fraction');

    const countInfo = await ee.data.computePromise(pixelCount);

    if (countInfo === 0) {
      console.log(`No valid pixels remaining for ${dateKey} (${targetDate}) after cloud masking.`);
      console.log("C2");
      return;
    }

    // Calculate the mean NDSI_Snow_Fraction
    const meanSnowFraction = maskedSnowFraction.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: sierraNevada,
      scale: scale,
      maxPixels: 1e9
    }).get('NDSI_Snow_Fraction');

    const meanInfo = await ee.data.computePromise(meanSnowFraction);

    if (meanInfo === null || isNaN(meanInfo)) {
      console.log(`Calculation failure for ${dateKey} (${targetDate}). Mean snow fraction is invalid.`);
      console.log("C3");
      return;
    }

    results[dateKey] = {
      mean: meanInfo,
      pixels: countInfo
    };
    console.log(`${dateKey} Mean Snow Fraction: ${meanInfo / 10000:.4f}, Valid Pixels: ${countInfo}`);
  }

  const jan1Snow = results['Jan 1'].mean;
  const apr1Snow = results['Apr 1'].mean;
  const may4Snow = results['May 4'].mean;

  // Compare snow fractions (higher value means more snow)
  const moreSnowOnJan1 = jan1Snow > apr1Snow && jan1Snow > may4Snow;

  if (moreSnowOnJan1) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
